let state=null,csrf="",currentTemplate="",currentKnowledge="",currentMeeting="",boardBucket="pre_review";
let selectedTasks=new Set(),wlSelected=new Set(),miData=null,kbChunks=[],lastMeetingItems=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const fmtDate=s=>s?new Date(s).toLocaleString("zh-CN",{hour12:false}):"—";
const pageClientId=(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`).replace(/[^a-zA-Z0-9_-]/g,'');
function clientSignal(action){return fetch(`/api/client/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_id:pageClientId}),keepalive:true,cache:'no-store'}).catch(()=>{})}
window.addEventListener('pageshow',()=>clientSignal('open'));
window.addEventListener('pagehide',()=>{const body=new Blob([JSON.stringify({client_id:pageClientId})],{type:'application/json'});if(!navigator.sendBeacon('/api/client/close',body))clientSignal('close')});
setInterval(()=>clientSignal('heartbeat'),15000);
async function api(path,options={},csrfRetry=true){const request={...options,headers:{"Content-Type":"application/json",...(options.headers||{})},cache:"no-store"};if(request.method&&request.method!=="GET")request.headers["X-CSRF-Token"]=csrf;const r=await fetch(path,request);let v;try{v=await r.json()}catch{v={error:`HTTP ${r.status}`}}if(!r.ok&&r.status===403&&csrfRetry&&/CSRF/i.test(v.error||'')){const freshResponse=await fetch('/api/workbench',{cache:'no-store'});if(freshResponse.ok){const fresh=await freshResponse.json();csrf=fresh.session?.csrf_token||'';state=fresh;return api(path,options,false)}}if(!r.ok)throw new Error(v.error||`HTTP ${r.status}`);return v}
function toast(value,bad=false){const el=$("#toast");el.hidden=false;el.textContent=typeof value==="string"?value:JSON.stringify(value,null,2);el.style.borderColor=bad?"#8b4250":"#587b31";clearTimeout(el._timer);el._timer=setTimeout(()=>el.hidden=true,12000)}
function tag(s){return `<span class="tag ${esc(s)}">${esc(s||"unknown")}</span>`}
function empty(text){return `<div class="empty">${esc(text)}</div>`}
const titles={overview:["WORKBENCH","工作台总览"],tasks:["TASKS","任务管理"],board:["NERVOUS TALK","项目看板"],timeline:["PROJECT HISTORY","项目时间线"],templates:["REPLY SYSTEM","回复模板"],draft:["AI ASSISTANT","AI 起草"],links:["RESOURCES","常用链接"],knowledge:["KNOWLEDGE BASE","知识库"],meetings:["COMMITTEE","会议纪要"],"meeting-items":["COMMITTEE QUEUE","上会项目"],notion:["AUTOMATION","Notion 同步"],audit:["SECURITY","审计记录"],settings:["CONFIGURATION","设置"]};
function switchView(name){$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===name));$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${name}`));$("#sectionEyebrow").textContent=titles[name][0];$("#sectionTitle").textContent=titles[name][1];if(name==='audit')loadAudit();if(name==='meeting-items')renderMeetingItems();if(name==='knowledge')ensureKbChunks();if(name==='notion'&&!state.notion_overview)loadNotionOverview()}

async function load(){try{state=await api("/api/workbench")}catch(e){if(!/登录/.test(e.message))throw e;const username=prompt("工作台用户名");const password=prompt("工作台密码");const login=await api("/api/login",{method:"POST",body:JSON.stringify({username,password})});csrf=login.csrf_token;state=await api("/api/workbench")}csrf=state.session.csrf_token;render()}
function render(){renderOverview();renderTasks();renderBoardTabs();renderBoard();renderTimeline();renderTemplates();renderDraftOptions();renderLinks();renderKnowledge();renderMeetings();renderNotion();renderSettings();$("#userBadge").textContent=`${state.session.username} · ${state.session.role}`;$("#connection").textContent=state.config.notion_configured?(state.config.auto_notion?"Notion 自动执行":"Notion 手动模式"):"Notion 待配置"}

function boardClassified(){return state.board?.classified||{}}
function preReview(){return boardClassified().spark_program?.pre_review||[]}
function nonProposal(){return boardClassified().spark_program?.non_proposal||[]}
function officialPosts(){return boardClassified().spark_program?.official||[]}
function renderOverview(){const tasks=state.tasks||[],jobs=state.jobs||[],b=boardClassified();$("#mOpen").textContent=tasks.filter(x=>!x.done).length;$("#mProgress").textContent=(b.in_progress||[]).length;$("#mMeeting").textContent=(b.submitted||[]).length+(b.pending||[]).length+preReview().length;$("#mVerified").textContent=jobs.filter(x=>x.status==='verified').length;$("#recentTasks").innerHTML=tasks.slice(0,6).map(taskCard).join('')||empty('暂无任务');$("#recentJobs").innerHTML=jobs.slice(0,6).map(jobCard).join('')||empty('暂无同步作业');$("#overviewTimeline").innerHTML=(state.timeline||[]).slice(0,8).map(p=>`<div class="compact-row"><span>${esc((p.created_at||'').slice(0,10))}</span><a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.title)}</a><span>${esc(p.author||'')}</span></div>`).join('')||empty('刷新看板后显示动态')}
function taskCard(t){return `<article class="item"><div><strong>${esc(t.title)}</strong><p>${esc(t.project||t.note||'')}</p></div>${t.done?tag('verified'):tag(t.automation_step?'pending':'open')}</article>`}
function jobCard(j){const title=j.project_name||`${j.workflow} · ${j.topic_id}`;const sub=`${j.workflow} · ${j.topic_id}`;return `<article class="item"><div><strong>${esc(title)}</strong><p class="muted"><small>${esc(sub)}${j.applicant?` · 申请人 ${esc(j.applicant)}`:''}</small></p><p>${esc(j.last_error||'')}</p><div>${(j.steps||[]).map(s=>tag(`${s.step}: ${s.status}`)).join(' ')}${j.stale?tag('已被覆盖'):''}</div>${j.payload&&!j.stale?`<button class="load-job" data-key="${esc(j.idempotency_key)}">载入修正</button>`:''} ${j.stale?`<button class="dismiss-job" data-key="${esc(j.idempotency_key)}">忽略</button>`:''}</div>${tag(j.status)}</article>`}

/* ============================== 任务页 ============================== */
const QUICK_TASKS=["更新 Notion Dashboard","Nervos Talk 回帖","Nervos Talk 发帖","跟进周报","中期审核","准备结项","撰写报告"];
function quickTaskType(title){if(/Notion/.test(title))return"更新 Notion Dashboard";if(/回帖/.test(title))return"Nervos Talk 回帖";if(/发帖/.test(title))return"Nervos Talk 发帖";if(/周报/.test(title))return"周报跟进";if(/审核|中期/.test(title))return"中期审核";if(/结项|报告/.test(title))return"结项处理";return"其他"}
function renderQuickAdd(){$("#quickAddBar").innerHTML=QUICK_TASKS.map(t=>`<button class="quick-add-btn" data-title="${esc(t)}">＋ ${esc(t)}</button>`).join('');$$('.quick-add-btn').forEach(x=>x.onclick=async()=>{const title=x.dataset.title;try{await api('/api/tasks',{method:'POST',body:JSON.stringify({title,type:quickTaskType(title),project:'',deadline:'',note:'',link:''})});await load();toast(`已添加任务：${title}`)}catch(e){toast(e.message,true)}})}
function taskMatches(t){const q=$("#taskSearch").value.toLowerCase(),f=$("#taskFilter").value;if(f==='open'&&t.done)return false;if(f==='done'&&!t.done)return false;return !q||[t.title,t.type,t.project,t.note].join(' ').toLowerCase().includes(q)}
function updateTaskSelectionUI(){const rows=$$("#taskRows .row-check");const visible=[...rows].map(x=>Number(x.dataset.id));const selVisible=visible.filter(id=>selectedTasks.has(id));$("#selectAllTasks").checked=rows.length>0&&selVisible.length===rows.length;$("#selectedTaskCount").textContent=`已选 ${selectedTasks.size} 项`}
function renderTasks(){renderQuickAdd();const rows=(state.tasks||[]).filter(taskMatches);$("#taskRows").innerHTML=rows.map(t=>`<tr class="task-row" data-id="${t.id}"><td><input class="check row-check" data-id="${t.id}" type="checkbox" ${selectedTasks.has(t.id)?'checked':''}></td><td><input class="check task-toggle" data-id="${t.id}" type="checkbox" ${t.done?'checked':''} ${t.verification_gated?'disabled title="由 Notion 回读验证自动完成"':''}></td><td><span class="task-title" data-detail="${t.id}">${esc(t.title)}</span>${t.note?`<br><small>${esc(t.note.slice(0,160))}</small>`:''}</td><td>${esc(t.type)}</td><td>${esc(t.project)}</td><td>${esc(t.deadline)}</td><td><button class="task-edit" data-id="${t.id}">编辑</button> ${!t.verification_gated?`<button class="task-delete danger" data-id="${t.id}">删除</button>`:''}${t.link?` <a href="${esc(t.link)}" target="_blank" rel="noreferrer">打开</a>`:''}</td></tr>`).join('')||`<tr><td colspan="7">${empty('没有符合条件的任务')}</td></tr>`;
$$('.task-toggle').forEach(x=>x.onchange=()=>toggleTask(x));$$('.task-edit').forEach(x=>x.onclick=()=>openTask(state.tasks.find(t=>t.id===Number(x.dataset.id))));$$('.task-delete').forEach(x=>x.onclick=async()=>{if(!confirm('确定删除此任务？'))return;try{await api(`/api/tasks/${x.dataset.id}`,{method:'DELETE'});selectedTasks.delete(Number(x.dataset.id));await load()}catch(e){toast(e.message,true)}});
$$('.row-check').forEach(x=>x.onchange=()=>{const id=Number(x.dataset.id);if(x.checked)selectedTasks.add(id);else selectedTasks.delete(id);updateTaskSelectionUI()});
$$('.task-title').forEach(x=>x.onclick=()=>showTaskDetail(Number(x.dataset.detail)));
$$('tr.task-row').forEach(tr=>tr.ondblclick=e=>{if(e.target.closest('input,button,a'))return;const id=Number(tr.dataset.id);openTaskLink(id)});updateTaskSelectionUI()}
function showTaskDetail(id){const t=(state.tasks||[]).find(x=>x.id===id);if(!t)return;const el=$("#taskDetail");el.hidden=false;el.innerHTML=`<div class="panel-head"><h2>${esc(t.title)}</h2><div><button id="copyTaskNote">复制备注</button><button id="closeTaskDetail">关闭</button></div></div><div class="facts"><div><span>类型</span><strong>${esc(t.type||'—')}</strong></div><div><span>项目</span><strong>${esc(t.project||'—')}</strong></div><div><span>截止</span><strong>${esc(t.deadline||'—')}</strong></div><div><span>链接</span><strong>${t.link?`<a href="${esc(t.link)}" target="_blank" rel="noreferrer">${esc(t.link)}</a>`:'—'}</strong></div><div><span>创建</span><strong>${esc(fmtDate(t.created_at))}</strong></div><div><span>完成</span><strong>${esc(fmtDate(t.completed_at))}</strong></div></div><p class="pre-wrap">${esc(t.note||'无备注')}</p>`;$("#copyTaskNote").onclick=()=>navigator.clipboard.writeText(t.note||t.title||'').then(()=>toast('已复制'));$("#closeTaskDetail").onclick=()=>el.hidden=true}
async function openTaskLink(id){try{const v=await api('/api/tasks/open-link',{method:'POST',body:JSON.stringify({id})});if(v.mode==='private')toast('已在无痕窗口打开（请手动登录论坛）')}catch(e){toast(e.message,true)}}
async function batchTasks(action){if(selectedTasks.size===0)return toast('请先勾选任务',true);if(action==='delete'&&!confirm(`确定删除选中的 ${selectedTasks.size} 个任务？`))return;try{const v=await api('/api/tasks/batch',{method:'POST',body:JSON.stringify({ids:[...selectedTasks],action})});selectedTasks.clear();await load();const parts=[];if(v.completed)parts.push(`完成 ${v.completed.length}`);if(v.deleted)parts.push(`删除 ${v.deleted.length}`);if(v.skipped)parts.push(`跳过 ${v.skipped.length}（Notion 验证门控）`);toast('批量操作：'+parts.join('，'))}catch(e){toast(e.message,true)}}
function exportTasksMd(){const rows=(state.tasks||[]).filter(taskMatches);const lines=['# 任务清单','',`| 状态 | 任务 | 类型 | 项目 | 截止 |`,'| --- | --- | --- | --- | --- |',...rows.map(t=>`| ${t.done?'✅':'⬜'} | ${t.title.replace(/\|/g,'/')} | ${t.type||''} | ${(t.project||'').replace(/\|/g,'/')} | ${t.deadline||''} |`)].join('\n');const blob=new Blob([lines],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='spark-tasks.md';a.click();URL.revokeObjectURL(a.href)}
async function toggleTask(el){try{await api(`/api/tasks/${el.dataset.id}/toggle`,{method:'POST',body:'{}'});await load()}catch(e){toast(e.message,true);await load()}}
function openTask(t={}){$("#taskDialogTitle").textContent=t.id?'编辑任务':'新增任务';for(const [id,key] of [['taskId','id'],['taskTitle','title'],['taskType','type'],['taskProject','project'],['taskDeadline','deadline'],['taskLink','link'],['taskNote','note']])$(`#${id}`).value=t[key]||'';$("#taskDialog").showModal()}
async function saveTask(){const id=$("#taskId").value,payload={title:$("#taskTitle").value,type:$("#taskType").value,project:$("#taskProject").value,deadline:$("#taskDeadline").value,link:$("#taskLink").value,note:$("#taskNote").value};if(!payload.title)return toast('请输入任务名称',true);await api(id?`/api/tasks/${id}/update`:'/api/tasks',{method:'POST',body:JSON.stringify(payload)});$("#taskDialog").close();await load()}

/* ============================== 项目看板 ============================== */
const buckets=[['pre_review','Pre-review'],['official','Official'],['submitted','Submitted'],['pending','Pending'],['in_progress','In Progress'],['rejection','Rejection'],['completion','Completion'],['closure','Closure']];
function bucketItems(bucket){const c=boardClassified();if(bucket==='pre_review')return[...preReview(),...nonProposal()];if(bucket==='official')return officialPosts();return c[bucket]||[]}
function whitelistMap(){return state.board_whitelist||{}}
function renderBoardStats(){const wl=Object.keys(whitelistMap()).length;const stats=[['Pre-review',preReview().length+nonProposal().length],['Official',officialPosts().length],['Submitted',(boardClassified().submitted||[]).length],['Pending',(boardClassified().pending||[]).length],['In-Progress',(boardClassified().in_progress||[]).length],['Rejection',(boardClassified().rejection||[]).length],['Completion',(boardClassified().completion||[]).length],['Closure',(boardClassified().closure||[]).length],['白名单',wl]];$("#boardStats").innerHTML=stats.map(([n,v])=>`<div class="stat-card"><span>${n}</span><strong>${v}</strong></div>`).join('')}
function renderBoardTabs(){renderBoardStats();$("#boardTabs").innerHTML=buckets.map(([k,n])=>`<button data-bucket="${k}" class="${k===boardBucket?'active':''}">${n} · ${bucketItems(k).length}</button>`).join('');$$('[data-bucket]').forEach(x=>x.onclick=()=>{boardBucket=x.dataset.bucket;renderBoardTabs();renderBoard()})}
function boardPrefix(p){const wl=whitelistMap(),pid=String(p.id);if(wl[pid])return{cls:'wl',text:`W→${wl[pid]}`};if(officialPosts().some(x=>String(x.id)===pid))return{cls:'official',text:'Official'};if(p.ai_classified==='non_proposal')return{cls:'non',text:'X'};if(p.ai_classified==='proposal')return{cls:'prop',text:'P'};return null}
function renderBoard(){const items=bucketItems(boardBucket);$("#boardUpdated").textContent=state.board?.last_update?`最后刷新：${fmtDate(state.board.last_update)}`:'尚未刷新';$("#boardGrid").innerHTML=items.map(projectCard).join('')||empty('此分组暂无项目');$$('.wl-check').forEach(x=>x.onchange=()=>{if(x.checked)wlSelected.add(x.dataset.id);else wlSelected.delete(x.dataset.id);updateWlBar()});$$('#boardGrid .card').forEach(card=>{card.ondblclick=e=>{if(e.target.closest('input,button,a,select'))return;const url=card.dataset.url;if(url)window.open(url,'_blank')}});updateWlBar()}
function projectCard(p){const pre=boardPrefix(p);const wl=whitelistMap();return `<article class="card" data-url="${esc(p.url||'')}"><h3><label class="inline-check" title="加入白名单"><input class="check wl-check" data-id="${esc(String(p.id))}" type="checkbox" ${wl[String(p.id)]?'checked':''}></label> ${pre?`<span class="board-prefix ${pre.cls}">[${esc(pre.text)}]</span> `:''}<a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.title)}</a></h3><p>${esc(p.author||p.original_poster_username||'未知作者')} · ${esc((p.created_at||'').slice(0,10))}${p.ai_classify_reason?` · ${esc(p.ai_classify_reason)}`:''}</p><div class="meta">${(p.tags||[]).map(x=>tag(x)).join('')}${tag(`${p.posts_count||0} 回复`)}</div><div class="actions"><button class="use-draft" data-url="${esc(p.url)}">用于起草</button></div></article>`}
function updateWlBar(){$("#wlCount").textContent=`已选中 ${wlSelected.size} 个帖子`;$("#wlAdd").disabled=wlSelected.size===0||!$("#wlTarget").value}
async function addWhitelist(){const target=$("#wlTarget").value;if(!target||wlSelected.size===0)return;try{const v=await api('/api/board/whitelist',{method:'POST',body:JSON.stringify({ids:[...wlSelected],target})});wlSelected.clear();$("#wlStatus").textContent=`已添加 ${v.added?.length||0} 个帖子 → ${target}`;await load()}catch(e){toast(e.message,true)}}

function renderTimeline(){const q=$("#timelineSearch").value.toLowerCase(),limit=Number($("#timelineLimit").value||50);const rows=(state.timeline||[]).filter(p=>!q||[p.title,p.author,(p.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)).slice(0,limit);$("#timelineRows").innerHTML=rows.map(p=>`<tr><td>${esc((p.created_at||'').slice(0,10))}</td><td><a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.title)}</a></td><td>${esc(p.author)}</td><td>${(p.tags||[]).map(tag).join(' ')}</td><td>${p.posts_count||0}</td></tr>`).join('')||`<tr><td colspan="5">${empty('暂无数据')}</td></tr>`}

/* ============================== 回复模板 ============================== */
function renderTemplates(){const names=Object.keys(state.templates||{});if(!currentTemplate)currentTemplate=names[0]||'';$("#templateList").innerHTML=names.map(n=>`<button data-template="${esc(n)}" class="${n===currentTemplate?'active':''}">${esc(n)}</button>`).join('')||empty('暂无模板');$$('[data-template]').forEach(x=>x.onclick=()=>{currentTemplate=x.dataset.template;renderTemplates()});const t=state.templates?.[currentTemplate]||{};$("#templateName").value=currentTemplate;$("#templateDesc").value=t.desc||'';$("#templateContent").value=t.template||''}
async function saveTemplate(){const old=currentTemplate,name=$("#templateName").value.trim();if(!name)return toast('模板名称不能为空',true);const all={...(state.templates||{})};if(old&&old!==name)delete all[old];all[name]={...(all[name]||{}),desc:$("#templateDesc").value,template:$("#templateContent").value};await api('/api/legacy/section',{method:'POST',body:JSON.stringify({section:'templates',value:all})});currentTemplate=name;await load();toast('模板已保存')}

/* ============================== AI 起草 ============================== */
const AI_MODELS={"kimi":["moonshot-v1-8k","moonshot-v1-32k","moonshot-v1-128k","moonshot-v1-auto"],"siliconflow":["deepseek-ai/DeepSeek-V4-Flash","deepseek-ai/DeepSeek-V3","deepseek-ai/DeepSeek-R1","Qwen/Qwen3.6-27B","Qwen/Qwen3-235B-A22B","Qwen/QwQ-32B","Pro/moonshotai/Kimi-K2.6","Pro/Qwen/Qwen3-235B-A22B","zai-org/GLM-5.2","Pro/MiniMaxAI/MiniMax-M2.5"]};
function draftProjects(){const c=boardClassified(),out=[];for(const bucket of['in_progress','pending','submitted']){for(const p of c[bucket]||[])out.push({id:p.id,title:p.title,url:p.url})}for(const p of preReview())out.push({id:p.id,title:p.title,url:p.url});return out}
function renderDraftOptions(){const t=$("#draftTemplate").value,c=$("#draftCharacter").value,m=$("#draftMeeting").value,u=$("#draftUrl").value,mo=$("#draftModel").value;$("#draftTemplate").innerHTML=Object.keys(state.templates||{}).map(x=>`<option>${esc(x)}</option>`).join('');$("#draftCharacter").innerHTML='<option value="">默认联络员风格</option>'+ (state.characters||[]).filter(x=>x.enabled).map(x=>`<option value="${esc(x.id)}">${esc(x.display_name||x.name)}</option>`).join('');$("#draftMeeting").innerHTML='<option value="">不关联</option>'+(state.meetings||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.date)} · ${esc(x.title)}</option>`).join('');const provider=state.ai?.provider||'siliconflow';$("#draftModel").innerHTML=(AI_MODELS[provider]||AI_MODELS.siliconflow).map(x=>`<option>${esc(x)}</option>`).join('');$("#draftProject").innerHTML='<option value="">手动输入 URL</option>'+draftProjects().map(p=>`<option value="${esc(p.url)}">${esc(p.title)}</option>`).join('');if(t)$("#draftTemplate").value=t;if(c)$("#draftCharacter").value=c;if(m)$("#draftMeeting").value=m;if(u)$("#draftUrl").value=u;if(mo)$("#draftModel").value=mo}
function loadResolutionPreview(){const id=$("#draftMeeting").value;const m=(state.meetings||[]).find(x=>String(x.id)===String(id));if(!m){$("#resolutionPreview").textContent='';return toast('请先选择关联会议',true)}const lines=(m.resolutions||[]).map(r=>`${r.project||''} | ${r.decision||''} | ${r.budget||''}`);$("#resolutionPreview").textContent=`已加载 ${lines.length} 条决议（已注入 Prompt）`}
async function generateDraft(){const b=$("#generateDraft");const provider=state.ai?.provider||'siliconflow';try{b.disabled=true;b.textContent='正在读取帖子并生成…';$("#draftStatus").textContent='生成中，预审模板为两阶段（分析→格式化），最长约 5 分钟';const v=await api('/api/ai/draft',{method:'POST',body:JSON.stringify({template:$("#draftTemplate").value,character:$("#draftCharacter").value,topic_url:$("#draftUrl").value,meeting_id:$("#draftMeeting").value,supplement:$("#draftSupplement").value,provider,model:$("#draftModel").value})});$("#draftOutput").value=v.content;$("#draftPrompt").value=v.prompt;if(v.analysis){$("#analysisDetails").hidden=false;$("#draftAnalysis").value=v.analysis}else $("#analysisDetails").hidden=true;$("#draftStatus").textContent=v.analysis_only?'阶段二失败，已回退为分析报告':'生成完成'}catch(e){toast(e.message,true);$("#draftStatus").textContent='生成失败'}finally{b.disabled=false;b.textContent='生成草稿'}}

/* ============================== 常用链接 ============================== */
function renderLinks(){$("#linkGrid").innerHTML=Object.entries(state.links||{}).map(([n,u])=>`<a class="link-card" href="${esc(u)}" target="_blank" rel="noreferrer"><strong>${esc(n)}</strong><span>${esc(u)}</span></a>`).join('')||empty('暂无链接')}

/* ============================== 知识库 ============================== */
function renderKnowledge(){const files=state.knowledge||[];$("#knowledgeList").innerHTML=files.map(x=>`<button data-kb="${esc(x.path)}" class="${x.path===currentKnowledge?'active':''}">${esc(x.path)}<br><small>${x.size} bytes</small></button>`).join('')||empty('未找到 knowledge 目录');$$('[data-kb]').forEach(x=>x.onclick=()=>loadKnowledge(x.dataset.kb));$("#toneContent").value=state.tone||'';$("#characterGrid").innerHTML=(state.characters||[]).map((x,i)=>`<article class="card"><label><input class="character-enabled" data-i="${i}" type="checkbox" ${x.enabled?'checked':''}> 启用 ${esc(x.display_name||x.name)}</label><p>${esc(x.description||'')}</p><details><summary>人物档案</summary><textarea class="character-content medium" data-i="${i}">${esc(x.content||'')}</textarea></details></article>`).join('')||empty('暂无人物角色')}
async function loadKnowledge(path){try{const v=await api(`/api/knowledge?path=${encodeURIComponent(path)}`);currentKnowledge=path;$("#knowledgeTitle").textContent=path;$("#knowledgeContent").value=v.content;renderKnowledge()}catch(e){toast(e.message,true)}}
async function ensureKbChunks(){if(kbChunks.length)return renderKbChunks();try{const idx=await api('/api/knowledge/index');const tags=(idx.tags||[]).map(x=>x.tag);const cur=$("#kbTagFilter").value;$("#kbTagFilter").innerHTML='<option value="">全部标签</option>'+tags.map(t=>`<option>${esc(t)}</option>`).join('');if(cur)$("#kbTagFilter").value=cur;const v=await api('/api/knowledge/chunks');kbChunks=v.chunks||[];renderKbChunks()}catch(e){toast(e.message,true)}}
function renderKbChunks(){const tag=$("#kbTagFilter").value;const rows=kbChunks.filter(c=>!tag||(c.tags||[]).includes(tag));$("#kbChunkList").innerHTML=rows.map(c=>`<button data-chunk="${esc(c.id)}">${esc(c.heading||c.id)}<br><small>${esc(c.file)} · ${c.chars} 字 · ${(c.tags||[]).join(', ')}</small></button>`).join('')||empty('没有匹配的知识块');$$('[data-chunk]').forEach(x=>x.onclick=()=>loadChunk(x.dataset.chunk))}
async function loadChunk(id){try{const v=await api(`/api/knowledge/chunks?id=${encodeURIComponent(id)}`);$("#kbChunkTitle").textContent=v.heading||v.id;$("#kbChunkMeta").textContent=`${v.file} · ${(v.tags||[]).join(', ')}`;$("#kbChunkContent").value=v.content||''}catch(e){toast(e.message,true)}}
async function rebuildIndex(){try{const v=await api('/api/knowledge/rebuild',{method:'POST',body:'{}'});kbChunks=[];await ensureKbChunks();toast(v.returncode===0?`索引重建完成\n${v.stdout||''}`:`索引重建失败\n${v.stderr||''}`,v.returncode!==0)}catch(e){toast(e.message,true)}}

/* ============================== 会议纪要 ============================== */
const DECISIONS=['通过','待定','拒绝','关闭','完成'];
function renderMeetings(){const meetings=state.meetings||[];if(!currentMeeting&&meetings[0])currentMeeting=meetings[0].id;$("#meetingList").innerHTML=meetings.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(x=>`<button data-meeting="${esc(x.id)}" class="${String(x.id)===String(currentMeeting)?'active':''}">${esc(x.date)}<br><strong>${esc(x.title)}</strong><br><small>${(x.resolutions||[]).length} 项决议</small></button>`).join('')||empty('暂无会议');$$('[data-meeting]').forEach(x=>x.onclick=()=>{currentMeeting=x.dataset.meeting;renderMeetings()});const m=meetings.find(x=>String(x.id)===String(currentMeeting))||{};$("#meetingDate").value=m.date||'';$("#meetingTitle").value=m.title||'';$("#meetingLink").value=m.meet_link||'';$("#meetingTalk").value=m.talk_topic_url||'';$("#meetingTranscript").value=m.transcript||'';$("#meetingSummary").value=m.ai_summary||'';renderResolutionRows(m);renderDraftOptions()}
function renderResolutionRows(m){const rows=(m.resolutions||[]);$("#resolutionRows").innerHTML=rows.map((r,i)=>`<div class="res-row" data-i="${i}"><input class="check res-check" data-i="${i}" type="checkbox" title="勾选后可删除"><input class="res-project" data-i="${i}" value="${esc(r.project||'')}" placeholder="项目名称"><select class="res-decision" data-i="${i}">${DECISIONS.map(d=>`<option ${d===r.decision?'selected':''}>${d}</option>`).join('')}</select><input class="res-round" data-i="${i}" value="${esc(r.round||'')}" placeholder="轮次" title="轮次"><input class="res-budget" data-i="${i}" value="${esc(r.budget||'')}" placeholder="预算" title="预算"><input class="res-note" data-i="${i}" value="${esc(r.note||'')}" placeholder="备注" title="备注"><input class="res-main" data-i="${i}" value="${esc(r.main_post_url||'')}" placeholder="主帖 URL" title="主帖 URL"><span class="res-talk"><input class="res-talk-url" data-i="${i}" value="${esc(r.talk_url||'')}" placeholder="关联帖 URL" title="关联帖 URL"><button class="res-fetch" data-i="${i}" title="获取 Talk 帖子内容并保存到本地">📎</button>${r.talk_file?`<small class="muted" title="${esc(r.talk_file)}">已存</small>`:''}</span></div>`).join('')||'<p class="muted">暂无决议，点击「➕ 添加决议」或「📥 导入纪要文本」</p>';
$$('.res-fetch').forEach(x=>x.onclick=()=>fetchTalkLink(Number(x.dataset.i)))}
function collectResolutions(){const rows=$$('#resolutionRows .res-row');return rows.map(row=>{const i=row.dataset.i;return{project:$(`.res-project[data-i="${i}"]`).value.trim(),decision:$(`.res-decision[data-i="${i}"]`).value,round:$(`.res-round[data-i="${i}"]`).value.trim(),budget:$(`.res-budget[data-i="${i}"]`).value.trim(),note:$(`.res-note[data-i="${i}"]`).value.trim(),main_post_url:$(`.res-main[data-i="${i}"]`).value.trim(),talk_url:$(`.res-talk-url[data-i="${i}"]`).value.trim()}}).filter(r=>r.project)}
function addResolutionRow(){const m=(state.meetings||[]).find(x=>String(x.id)===String(currentMeeting));if(!m)return toast('请先新建或选择会议',true);const rows=collectResolutions();rows.push({project:'',decision:'待定',round:'',budget:'',note:'',main_post_url:'',talk_url:''});m.resolutions=rows;renderResolutionRows(m)}
function deleteSelectedResolutions(){const checked=$$('.res-check:checked').map(x=>Number(x.dataset.i));if(!checked.length)return toast('请先勾选要删除的决议',true);const m=(state.meetings||[]).find(x=>String(x.id)===String(currentMeeting));if(!m)return;const rows=collectResolutions();m.resolutions=rows.filter((_,i)=>!checked.includes(i));renderResolutionRows(m);toast('已移除（保存会议后生效）')}
async function fetchTalkLink(index){const m=(state.meetings||[]).find(x=>String(x.id)===String(currentMeeting));if(!m)return;const rows=collectResolutions();const url=rows[index]?.talk_url||prompt('输入 Talk 帖子 URL');if(!url)return;try{const v=await api(`/api/meetings/${currentMeeting}/link-talk`,{method:'POST',body:JSON.stringify({index,url})});toast(`已获取并保存：${v.file}`);await load()}catch(e){toast(e.message,true)}}
async function refreshResPosts(){if(!currentMeeting)return toast('请先选择会议',true);try{const v=await api(`/api/meetings/${currentMeeting}/refresh-posts`,{method:'POST',body:'{}'});toast(`已重新匹配主帖 ${v.matched}/${v.total}`);await load()}catch(e){toast(e.message,true)}}
function meetingPayload(){return{date:$("#meetingDate").value,title:$("#meetingTitle").value,meet_link:$("#meetingLink").value,talk_topic_url:$("#meetingTalk").value,resolutions:collectResolutions(),transcript:$("#meetingTranscript").value,ai_summary:$("#meetingSummary").value}}
function exportMeetingMd(){const m=(state.meetings||[]).find(x=>String(x.id)===String(currentMeeting));if(!m)return toast('请先选择会议',true);const lines=[`# ${m.title||'委员会会议'}`,``,`日期：${m.date||''}`,`Meet：${m.meet_link||''}`,`Talk：${m.talk_topic_url||''}`,'','## 决议','','| 项目 | 决议 | 轮次 | 预算 | 备注 |','| --- | --- | --- | --- | --- |',...(m.resolutions||[]).map(r=>`| ${(r.project||'').replace(/\|/g,'/')} | ${r.decision||''} | ${r.round||''} | ${(r.budget||'').replace(/\|/g,'/')} | ${(r.note||'').replace(/\|/g,'/')} |`),'','## AI 总结','',m.ai_summary||'','','## 转写文本','',m.transcript||''].join('\n');const blob=new Blob([lines],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`meeting-${m.date||'unknown'}.md`;a.click();URL.revokeObjectURL(a.href)}
let importParsed=null;
async function parseMeetingText(mode){const text=$("#importMeetingRaw").value.trim();if(!text){$("#importStatus").textContent='❌ 请先粘贴会议纪要文本';return}$("#importStatus").textContent='解析中…';try{const v=await api('/api/meetings/parse',{method:'POST',body:JSON.stringify({text,mode})});importParsed=v.parsed;$("#importPreview").value=`日期: ${importParsed.date||''}\n标题: ${importParsed.title||''}\n\n`+(importParsed.resolutions||[]).map((r,i)=>`${i+1}. ${r.project||''} | ${r.decision||''} | ${r.budget||''} | ${(r.note||'').slice(0,80)}`).join('\n');$("#importStatus").textContent=`✅ 解析完成：${(importParsed.resolutions||[]).length} 条决议`}catch(e){$("#importStatus").textContent=`❌ ${e.message}`}}
async function confirmImportMeeting(){if(!importParsed||(!importParsed.date&&!importParsed.title&&!(importParsed.resolutions||[]).length))return toast('请先解析内容',true);try{const m=await api('/api/meetings',{method:'POST',body:JSON.stringify({date:importParsed.date||new Date().toISOString().slice(0,10),title:importParsed.title||'导入的会议',resolutions:importParsed.resolutions||[]})});currentMeeting=m.id;$("#importMeetingDialog").close();$("#importStatus").textContent='';await load();toast(`已导入会议纪要：${m.title}，共 ${(m.resolutions||[]).length} 条决议`)}catch(e){toast(e.message,true)}}

/* ============================== 上会项目 ============================== */
function renderMeetingItems(){if(!lastMeetingItems){$("#mi-in_progress").innerHTML=empty('点击「刷新上会项目」开始分析');$("#mi-pending").innerHTML='';$("#mi-submitted").innerHTML='';return}const items=lastMeetingItems.items||{};for(const key of['in_progress','pending','submitted']){const list=items[key]||[];$("#miCount-"+key).textContent=`(${list.length})`;$("#mi-"+key).innerHTML=list.map((it,i)=>{const mark=`${it.overdue_7d?'[超7天] ':''}${it.irrelevant_mark||''}`;return `<div class="mi-item" data-key="${key}" data-i="${i}"><strong>${esc(mark)}${esc(it.title)}</strong><small>${esc(it.author||'')} ${it.ai_summary?`· ${esc(it.ai_summary)}`:''}</small></div>`}).join('')||`<p class="muted mi-empty">无需上会</p>`;$$("#mi-"+key+" .mi-item").forEach(el=>{el.onclick=()=>showMiDetail(items[el.dataset.key][Number(el.dataset.i)]);el.ondblclick=()=>{const it=items[el.dataset.key][Number(el.dataset.i)];if(it.url)window.open(it.url,'_blank')}})}$("#miStatus").textContent=lastMeetingItems.updated_at?`最后分析：${fmtDate(lastMeetingItems.updated_at)}`:''
}
function showMiDetail(it){if(!it)return;const status=[];if(it.overdue_7d)status.push('委员会回复超7天未收到发帖人回应');else status.push('委员会未回复发帖人最新消息');if(it.irrelevant_mark)status.push('含无关回复');$("#miDetail").innerHTML=`<h2>${esc(it.title||'Unknown')}</h2><p class="muted">作者: ${esc(it.author||'Unknown')} · 分类: ${esc(it.category||'')}</p><p>${esc(status.join('　'))}</p><p><strong>AI 总结:</strong> ${esc(it.ai_summary||'—')}</p><h3>发帖人最新回复</h3><p class="pre-wrap">${esc(it.latest_op_content||'无内容')}</p><div class="actions"><a class="button-link" href="${esc(it.url)}" target="_blank" rel="noreferrer">打开帖子 ↗</a></div>`}
async function refreshMeetingItems(){const b=$("#miRefresh");try{b.disabled=true;b.textContent='正在分析…';$("#miStatus").textContent='正在获取帖子详情，帖子较多时可能需要几分钟…';const v=await api('/api/meeting-items/refresh',{method:'POST',body:'{}'});lastMeetingItems=v;renderMeetingItems();$("#miStatus").textContent='正在生成 AI 总结…';try{const s=await api('/api/meeting-items/summarize',{method:'POST',body:'{}'});if(s.items){lastMeetingItems.items=s.items;lastMeetingItems.updated_at=s.updated_at}renderMeetingItems()}catch(e){/* 无 API Key 时跳过 */}}catch(e){toast(e.message,true)}finally{b.disabled=false;b.textContent='🔄 刷新上会项目'}}

/* ============================== Notion / 设置 / 审计 ============================== */
function renderNotion(){const jobs=(state.jobs||[]);const active=jobs.filter(x=>!x.stale);$("#nPending").textContent=active.filter(x=>['queued','partial','ready','needs_input'].includes(x.status)).length;$("#nConflict").textContent=active.filter(x=>x.status==='conflict').length;$("#nVerified").textContent=jobs.filter(x=>x.status==='verified'||x.status==='core_verified').length;const groups={};jobs.forEach(j=>{const k=String(j.topic_id||'unknown');(groups[k]=groups[k]||[]).push(j)});const act=g=>g.some(x=>!x.stale)?0:1;const sorted=Object.entries(groups).sort((a,b)=>act(a[1])-act(b[1])||String((a[1][0]||{}).project_name||a[0]).localeCompare(String((b[1][0]||{}).project_name||b[0])));$("#projectJobs").innerHTML=sorted.map(([k,v])=>projectJobCard(k,v)).join('')||empty('暂无同步作业');renderNotionSources()}
function projectJobCard(topicId,jobs){const first=jobs[0]||{};const name=first.project_name||`帖子 ${topicId}`;const applicant=first.applicant||'';const rows=jobs.map(j=>`<div class="item"><div><strong>${esc(j.workflow)}</strong><p class="muted"><small>帖子 ${esc(j.topic_id)}</small></p><p>${esc(j.last_error||'')}</p><div>${(j.steps||[]).map(s=>tag(`${s.step}: ${s.status}`)).join(' ')}${j.stale?tag('已被覆盖'):''}</div>${j.payload&&!j.stale?`<button class="load-job" data-key="${esc(j.idempotency_key)}">载入修正</button>`:''} ${j.stale?`<button class="dismiss-job" data-key="${esc(j.idempotency_key)}">忽略</button>`:''}</div>${tag(j.status)}</div>`).join('');return `<article class="card"><h3>${esc(name)}</h3><p>${applicant?`申请人：${esc(applicant)}`:'&nbsp;'}</p><div class="stack">${rows}</div></article>`}
const NOTION_SOURCE_NAMES={fund_allocations:'资金分配表 / Fund Allocations',transactions:'交易记录表 / Transactions',ongoing_projects:'进行中项目表 / Ongoing Projects',completed_projects:'已完成项目表 / Completed Projects'};
async function loadNotionOverview(){try{state.notion_overview=await api('/api/notion/overview');renderNotionSources()}catch(e){/* 未配置 Notion 时静默 */}}
function renderNotionSources(){const el=$("#notionSources"),st=$("#notionOverviewStatus");if(!el)return;const ov=state.notion_overview;if(!ov||!ov.sources||!Object.keys(ov.sources).length){el.innerHTML=empty('尚未检索 Notion 表单，点击「重新检索并对账」');if(st)st.textContent='';return}if(st)st.textContent=ov.updated_at?`最后检索：${fmtDate(ov.updated_at)}`:'';el.innerHTML=Object.entries(ov.sources).map(([k,v])=>`<details ${k==='ongoing_projects'?'open':''}><summary>${NOTION_SOURCE_NAMES[k]||k} · ${v.count||0} 行</summary><div class="stack">${(v.rows||[]).map(r=>`<div class="compact-row"><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title||r.id)}</a>${r.status?`<span>${esc(r.status)}</span>`:''}</div>`).join('')||empty('空表')}</div></details>`).join('')}
/* ============================== Notion 网页预览 ============================== */
let previewTabs=[],previewLoaded=new Set();
async function loadNotionPreview(){try{const v=await api('/api/notion/preview');previewTabs=(v&&v.tabs)||[]}catch(e){previewTabs=[]}renderPreviewTabs()}
function renderPreviewTabs(){const bar=$("#previewTabs"),frames=$("#previewFrames");if(!bar||!frames)return;previewLoaded=new Set();const fb=$("#previewFallback");if(fb)fb.hidden=true;if(!previewTabs.length){bar.innerHTML='';frames.innerHTML='<p class="muted preview-empty">未配置预览页面</p>';return}bar.innerHTML=previewTabs.map((t,i)=>`<span class="preview-tab"><button data-pi="${i}" class="${i===0?'active':''}">${esc(t.label)}</button>${t.url?`<a class="preview-open-link" href="${esc(t.url)}" target="_blank" rel="noreferrer" title="在 Notion 中打开">↗</a>`:''}</span>`).join('');frames.innerHTML=previewTabs.map((t,i)=>`<iframe class="preview-frame" data-pi="${i}" data-src="${esc(t.proxy||t.url)}" data-proxied="${t.proxy?'1':''}" loading="lazy" style="display:${i===0?'block':'none'}" title="${esc(t.label)}"></iframe>`).join('');bar.querySelectorAll('button').forEach(b=>b.onclick=()=>activatePreview(Number(b.dataset.pi)));activatePreview(0)}
function checkPreviewFrame(f){if(f.dataset.proxied!=='1')return;const fb=$("#previewFallback");if(!fb)return;let failed=false;try{const doc=f.contentDocument;if(!doc||!doc.body||doc.querySelector('[data-spark-proxy-error]'))failed=true}catch(e){failed=true}if(failed)fb.hidden=false}
function activatePreview(i){const bar=$("#previewTabs"),frames=$("#previewFrames");if(!bar||!frames)return;bar.querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.pi)===i));frames.querySelectorAll('iframe').forEach(f=>{const on=Number(f.dataset.pi)===i;if(on){if(!previewLoaded.has(i)){f.addEventListener('load',()=>checkPreviewFrame(f));f.src=f.dataset.src;previewLoaded.add(i)}f.style.display='block'}else{f.style.display='none'}})}
/* ============================== 链上交易检索 ============================== */
let chainPreview={mode:null,only:[]};
const CHAIN_DIRECTION_NAMES={out:'提款',in:'存款'};
function chainRowHtml(row,extra=''){return `<div class="chain-row"><strong>${esc(row.tx_hash||'')}</strong><br><span class="muted">${esc(row.date||'—')} · ${esc(row.type||'')} · ${esc(row.amount||'')}${row.direction?` · ${esc(CHAIN_DIRECTION_NAMES[row.direction]||row.direction)}`:''}</span>${row.purpose?`<br><span>${esc(row.purpose)}</span>`:''}${extra}</div>`}
async function scanChainMain(){const b=$('#scanChainMain'),st=$('#chainScanStatus'),box=$('#chainPreview');try{b.disabled=true;b.textContent='正在拉取链上交易…';st.textContent='主钱包全量检索中，可能需要几分钟';box.innerHTML='';const v=await api('/api/chain/scan-main');chainPreview={mode:'main',only:[...(v.missing||[]),...(v.mismatched||[])].map(r=>r.tx_hash)};const rows=[...(v.missing||[]).map(r=>chainRowHtml(r)),...(v.mismatched||[]).map(r=>chainRowHtml(r,`<br><span class="muted">不一致：${esc(Object.entries(r.diffs||{}).map(([k,d])=>`${k} ${d.actual||'空'}→${d.expected}`).join('；'))}</span>`)),...(v.extra||[]).map(r=>`<div class="chain-row"><strong>${esc(r.tx_hash||'')}</strong><br><span class="muted">表内多余（链上未找到，留待人工判断，不会自动删除）</span></div>`)];box.innerHTML=`<div class="chain-summary"><span>数据时间 ${esc(fmtDate(v.updated_at))}</span><span>已扫描 ${v.scanned??0} 笔</span><span>将新增 <strong>${(v.missing||[]).length}</strong> 行</span><span>不一致 <strong>${(v.mismatched||[]).length}</strong> 行</span><span>表内多余 <strong>${(v.extra||[]).length}</strong> 行</span><span class="flex-spacer"></span><button id="applyChainMain" class="primary" ${chainPreview.only.length?'':'disabled'}>确认写入（新增+修正）</button></div>`+(rows.join('')||empty('链上与表单一致，没有差异'));const apply=$('#applyChainMain');if(apply)apply.onclick=applyChainMain;st.textContent='预览完成，请核对后再确认写入'}catch(e){st.textContent='';toast(e.message,true)}finally{b.disabled=false;b.textContent='检索主钱包交易'}}
async function applyChainMain(){const b=$('#applyChainMain');if(!chainPreview.only.length)return toast('没有需要写入的交易',true);try{b.disabled=true;b.textContent='正在写入…';const v=await api('/api/chain/apply-main',{method:'POST',body:JSON.stringify({only:chainPreview.only})});await loadNotionOverview();toast(`写入完成\n新增 ${(v.created||[]).length} 行：${(v.created||[]).join(', ')||'无'}\n修正 ${(v.updated||[]).length} 行：${(v.updated||[]).join(', ')||'无'}\n跳过 ${(v.skipped||[]).length} 行\n失败 ${(v.errors||[]).length} 行${(v.errors||[]).length?'\n'+v.errors.map(x=>`${x.tx_hash}: ${x.error}`).join('\n'):''}`,(v.errors||[]).length>0);$('#chainPreview').innerHTML=''}catch(e){toast(e.message,true)}finally{b.disabled=false;b.textContent='确认写入（新增+修正）'}}
async function scanChainMultisig(){const b=$('#scanChainMultisig'),st=$('#chainScanStatus'),box=$('#chainPreview');try{b.disabled=true;b.textContent='正在拉取多签交易…';st.textContent='检索各项目多签钱包中，可能需要几分钟';box.innerHTML='';const v=await api('/api/chain/scan-multisig');const items=v.multisig||[];chainPreview={mode:'multisig',only:items.flatMap(m=>(m.rows||[]).map(r=>r.tx_hash))};let totalRows=0,totalExisting=0;const sections=items.map(m=>{totalRows+=(m.rows||[]).length;totalExisting+=m.existing||0;return `<div class="chain-row"><strong>${esc(m.project||m.multisig)}</strong><br><span class="muted">${esc(m.multisig||'')} · 已有 ${m.existing||0} 行</span>${m.source?'':'<br><span class="muted">⚠ 项目页缺少「资金使用情况」内联库</span>'}${(m.rows||[]).map(r=>chainRowHtml(r)).join('')}</div>`});box.innerHTML=`<div class="chain-summary"><span>数据时间 ${esc(fmtDate(v.updated_at))}</span><span>已知项目多签 <strong>${items.length}</strong> 个</span><span>将新增 <strong>${totalRows}</strong> 行</span><span>内联库已有 ${totalExisting} 行</span><span class="flex-spacer"></span><button id="applyChainMultisig" class="primary" ${totalRows?'':'disabled'}>确认写入</button></div>`+(sections.join('')||empty('没有发现符合条件的项目多签或缺失交易'));const apply=$('#applyChainMultisig');if(apply)apply.onclick=applyChainMultisig;st.textContent='预览完成，请核对后再确认写入'}catch(e){st.textContent='';toast(e.message,true)}finally{b.disabled=false;b.textContent='检索多签钱包交易'}}
async function applyChainMultisig(){const b=$('#applyChainMultisig');try{b.disabled=true;b.textContent='正在写入…';const v=await api('/api/chain/apply-multisig',{method:'POST',body:'{}'});toast(`写入完成：新增 ${(v.written||[]).length} 行${(v.errors||[]).length?`\n失败 ${v.errors.length} 行：${v.errors.map(x=>`${x.multisig||''} ${x.tx_hash||''}: ${x.error}`).join('\n')}`:''}`,(v.errors||[]).length>0);$('#chainPreview').innerHTML=''}catch(e){toast(e.message,true)}finally{b.disabled=false;b.textContent='确认写入'}}

// 「显示上次结果」：只读服务端扫描缓存渲染到预览区，不触发链上检索，也不提供写入按钮
function chainCacheNote(updatedAt,count){return `<div class="chain-summary"><span>缓存数据时间 ${esc(fmtDate(updatedAt))}</span><span>共 <strong>${count}</strong> 条</span><span class="muted">（上次检索结果，只读显示；点「检索」按钮可续查更新）</span></div>`}
async function showChainMainCache(){const st=$('#chainScanStatus'),box=$('#chainPreview');st.textContent='读取本地缓存…';try{const v=await api('/api/chain/scan-main?cached=1');if(!v.cached){box.innerHTML=empty('还没有缓存的扫描结果，请先点「检索主钱包交易」');st.textContent='';return}
chainPreview={mode:null,only:[]};
const rows=[...(v.missing||[]).map(r=>chainRowHtml(r)),...(v.mismatched||[]).map(r=>chainRowHtml(r,`<br><span class="muted">不一致：${esc(Object.entries(r.diffs||{}).map(([k,d])=>`${k} ${d.actual||'空'}→${d.expected}`).join('；'))}</span>`)),...(v.extra||[]).map(r=>`<div class="chain-row"><strong>${esc(r.tx_hash||'')}</strong><br><span class="muted">表内多余（链上未找到，留待人工判断，不会自动删除）</span></div>`)];
box.innerHTML=chainCacheNote(v.updated_at,(v.missing||[]).length+(v.mismatched||[]).length+(v.extra||[]).length)+(rows.join('')||empty('缓存结果为空'));st.textContent='已显示上次主钱包扫描缓存'}catch(e){st.textContent='';toast(e.message,true)}}
async function showChainMultisigCache(){const st=$('#chainScanStatus'),box=$('#chainPreview');st.textContent='读取本地缓存…';try{const v=await api('/api/chain/scan-multisig?cached=1');const items=v.multisig||[];if(!v.cached){box.innerHTML=empty('还没有缓存的多签扫描结果，请先点「检索多签钱包交易」');st.textContent='';return}
chainPreview={mode:null,only:[]};let totalRows=0,totalExisting=0;
const sections=items.map(m=>{totalRows+=(m.rows||[]).length;totalExisting+=m.existing||0;return `<div class="chain-row"><strong>${esc(m.project||m.multisig)}</strong><br><span class="muted">${esc(m.multisig||'')} · 已有 ${m.existing||0} 行</span>${(m.rows||[]).map(r=>chainRowHtml(r)).join('')}</div>`});
box.innerHTML=chainCacheNote(v.updated_at,totalRows)+`<div class="chain-summary"><span>已知项目多签 <strong>${items.length}</strong> 个</span><span>内联库已有 ${totalExisting} 行</span></div>`+(sections.join('')||empty('缓存结果为空'));st.textContent='已显示上次多签扫描缓存'}catch(e){st.textContent='';toast(e.message,true)}}

function renderSettings(){$("#settingProvider").value=state.ai?.provider||'siliconflow';$("#settingModel").value=state.ai?.model||'';$("#settingAutoNotion").checked=!!state.config?.auto_notion;$("#settingTeamMode").checked=!!state.config?.team_mode;$("#systemFacts").innerHTML=`<div><span>程序版本</span><strong>${esc(state.config.version||'未知')}</strong></div><div><span>服务地址</span><strong>${esc(location.host)}</strong></div><div><span>页面关闭</span><strong>自动释放端口</strong></div><div><span>团队模式</span><strong>${state.config.team_mode?'已开启':'关闭'}</strong></div><div><span>Notion Token</span><strong>${state.config.notion_configured?'已配置':'未配置'}</strong></div><div><span>自动写入</span><strong>${state.config.auto_notion?'开启':'关闭'}</strong></div><div><span>AI Key</span><strong>${state.ai?.has_key?'已配置':'未配置'}</strong></div>`}
async function loadAudit(){try{const v=await api('/api/audit');$("#auditRows").innerHTML=(v.events||[]).map(x=>`<tr><td>${esc(fmtDate(x.created_at))}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td><td>${esc(x.target)}</td><td><small>${esc(x.details_json)}</small></td></tr>`).join('')||`<tr><td colspan="5">${empty('暂无审计记录')}</td></tr>`}catch(e){toast(e.message,true)}}

